# cov.ps1 -- Verilator code-coverage suite driver for the mega138kpro-sfp RTL.
#
# Builds coverage-instrumented (VL_COVERAGE=ON) Verilator twins of the sim/
# self-checking benches into build/cov/, runs them (each dumps its own
# coverage.dat), then merges with verilator_coverage and renders BOTH an
# --annotate source tree and an lcov .info under build/cov/report/ (git-ignored).
# The committed baseline is doc/coverage.md (regenerated by tools/cov_summary.py).
#
# These are the SAME SV benches `ninja sim` runs under iverilog, re-elaborated
# by Verilator with --main (Verilator emits the C++ main; the benches self-check
# via their own initial blocks + $finish). Coverage is scoped to this repository's
# synthesizable RTL (rtl/*.sv) by coverage.vlt; the benches, the SerDes stub and
# the sibling repositories' sources are instrumentation-excluded.
#
# NOT a gate (instrumentation costs sim speed) -- opt-in.
#
# The steps are retrosim-build/tools/vl_cov.ps1 (via vl_cov_lib.ps1); this
# file names what is particular to this repository.
#
# Usage:
#   vl\cov.ps1            # configure + build the twins + run + merge + report
#   vl\cov.ps1 -NoBuild   # reuse the existing build/cov twins, just re-run + report
param(
    [switch]$NoBuild      # skip the (re)configure + build of the coverage twins
)
& (Join-Path $PSScriptRoot '..\..\..\retrosim-build\tools\vl_cov.ps1') -VlRoot $PSScriptRoot -NoBuild:$NoBuild
exit $LASTEXITCODE
